    ensures s == add(l)
{
    var ll := l;
    s := 0;
    while ll != Nil
        decreases ll
        invariant add(l) == s + add(ll)
        {
            s := s + ll.head;
            ll:= ll.tail;
        }
    assert s == add(l);
}


